mapper.update:
	UPDATE AFA210 SET
	    LAST_MDFR_ID = #{LAST_MDFR_ID},
	    LAST_MDFCN_DT = SYSDATE,
        DEL_YN = 'Y'
    WHERE 1=1
        AND RESRCE_NO = #{RESRCE_NO}
        AND RPT_SE_CD = #{RPT_SE_CD__origin}
        AND TASKWK_RPT_SN = #{TASKWK_RPT_SN__origin}
        AND SEMSTR_SE_CD = #{SEMSTR_SE_CD}
        AND RPT_MM = #{RPT_MM}


        SELECT NVL(MAX(TASKWK_RPT_SN),0)+1 AS TASKWK_RPT_SN
        FROM AFA210


	MERGE INTO AFA210 A
	USING DUAL ON
	(
	   A.RESRCE_NO = #{RESRCE_NO}
	       AND A.RPT_SE_CD = #{RPT_SE_CD}
	       AND A.TASKWK_RPT_SN = #{TASKWK_RPT_SN}
	       AND A.SEMSTR_SE_CD = #{SEMSTR_SE_CD}
	       AND A.RPT_MM = #{RPT_MM}
	       AND A.DEL_YN = 'N'
	)
	WHEN MATCHED THEN
	   UPDATE SET
	       RPT_CN = #{RPT_CN}
	       , LAST_MDFR_ID = #{LAST_MDFR_ID}
	       , LAST_MDFCN_DT = SYSDATE
	WHEN NOT MATCHED THEN
	   INSERT(
	       RESRCE_NO
           , RPT_SE_CD
           , TASKWK_RPT_SN
           , RPT_CN
           , ATFINO
           , APLY_YMD
           , APLY_PIC_NO
           , APRV_STTS_SE_CD
           , SEMSTR_SE_CD
           , RPT_MM
           , FRST_RGTR_ID
           , LAST_MDFR_ID
	   )
	   VALUES(
	       #{RESRCE_NO }
		   , #{RPT_SE_CD }
		   , (SELECT NVL(MAX(TASKWK_RPT_SN),0)+1
                FROM AFA210)
		   , #{RPT_CN }
		   , #{ATFINO }
		   , TO_CHAR(SYSDATE,'YYYYMMDD')
		   , #{APLY_PIC_NO }
		   , #{APRV_STTS_SE_CD }
		   , #{SEMSTR_SE_CD }
		   , #{RPT_MM }
		   , #{FRST_RGTR_ID }
		   , #{LAST_MDFR_ID }
	   )

mapper.select:

/*selectCheckResrce 월간업무보고 저장 체크(실행사업, 교육과정 등 맞물려있는지) - 이승재*/
SELECT COUNT(*)
FROM SDA100 A
JOIN SDA420 B
    ON A.SRVC_EXCN_BIZ_NO = B.SRVC_EXCN_BIZ_NO
JOIN SAA000 C
    ON A.RSFR_INST_NO = C.INST_NO
JOIN AFA310 D
    ON D.SRVC_EXCN_BIZ_NO = B.SRVC_EXCN_BIZ_NO
JOIN SDA400 E
    ON B.SRVC_BIZ_NO = E.SRVC_BIZ_NO
WHERE A.RESRCE_NO = #{RESRCE_NO}
    AND B.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
    AND C.INST_NO = #{INST_NO}
    AND D.SEMSTR_SE_CD = #{SEMSTR_SE_CD}
    AND E.BIZ_YR = #{BIZ_YR}


    /*selectCheckMnthngTaskwk 월간업무보고 저장 체크(월간업무보고 중복) - 이승재*/
    SELECT TASKWK_RPT_SN
	FROM AFA210
	WHERE RESRCE_NO = #{RESRCE_NO}
	    AND RPT_SE_CD = '02'
	    AND SEMSTR_SE_CD = #{SEMSTR_SE_CD}
	    AND RPT_MM = #{RPT_MM}
	    AND DEL_YN = 'N'
